head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf00000";

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — popupResult, ISREAL, message, errorCode, loginFailCnt, corp_usr_tp_cd, integ_usr_id, encryp_pw

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_popupResult", fn: function(){ return (!(String(((dma_pageContext.get("popupResult") ?? "")) == null ? '' : ((dma_pageContext.get("popupResult") ?? ""))).length === 0) && (((dma_pageContext.get("popupResult") ?? "")) && typeof ((dma_pageContext.get("popupResult") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("popupResult") ?? "")).getRowCount() : ((((dma_pageContext.get("popupResult") ?? "")) == null) ? 0 : (((dma_pageContext.get("popupResult") ?? "")).length || 0))) > 0); } }, { id: "img_17", fn: function(){ return ((dma_pageContext.get("ISREAL") ?? "") === 'localhost' || (dma_pageContext.get("ISREAL") ?? "") === 'dev' || (dma_pageContext.get("ISREAL") ?? "") === 'test1'|| (dma_pageContext.get("ISREAL") ?? "") === 'test2'); } }, { id: "c_otherwise_18", fn: function(){ return (!(((dma_pageContext.get("ISREAL") ?? "") === 'localhost' || (dma_pageContext.get("ISREAL") ?? "") === 'dev' || (dma_pageContext.get("ISREAL") ?? "") === 'test1'|| (dma_pageContext.get("ISREAL") ?? "") === 'test2'))); } }, { id: "if_ISREAL", fn: function(){ return ((dma_pageContext.get("ISREAL") ?? "") !== 'dr1' || (dma_pageContext.get("ISREAL") ?? "") !== 'dr2'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_4", entity: "dlt_popupResult", countIds: [], cells: [{ childId: "ipt_contnId", fn: function (v, i) { return String(v("contnId")); } }, { childId: "ipt_notiDd", fn: function (v, i) { return String(v("notiDd")); } }, { childId: "ipt_endDd", fn: function (v, i) { return String(v("endDd")); } }] },
        { genId: "c_foreach_24", entity: "dlt_result", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("contnTitle")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("regDd")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $('body').addClass("main");
        scwin.mainc_relocate();
        scwin.login_type_init();
        $("div.notice-section .slide").simple_slideshow2({ interval: 3000, btnp: 'div.notice-section a.btn-prev', btnn: 'div.notice-section a.btn-next', hover_event: false });
        $(window).resize(function() {
                scwin.mainc_relocate();
        });
        if ($.browser.msie === true && ($.browser.version === "7.0" || $.browser.version === "6.0")) {
            try {
                $('#wrapper-main div.notice-section a.btn-prev').is(":hidden");
                $('#wrapper-main div.notice-section a.btn-next').is(":hidden");
            } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldbnf00000' });
                const tmp = 1;
            }
        }
        $('div.loginbox.form div.line').eq(1).children("input").bind('focus', function() {
                $(this).replaceWith($(this).clone().attr('type', 'password').bind("focusout", function() {
                            $(this).replaceWith($(this).clone().attr('type', 'text'));
                }));
        });
        $c.util.getComponent("ipt_integUsrId").focus();
        const fm = (document.form || { elements: [] });
        let _cnt = 0;
        if (fm.contn_id != null) {
            _cnt = $c.util.getComponent('dlt_popupResult').getRowCount();
            if (_cnt == null) {
                if (scwin.getCookie("pop_emergency") === "") {
                    let startdd = $c.util.getComponent('ipt_notiDd').getValue() + "";
                    let enddd = $c.util.getComponent('ipt_endDd').getValue() + "";
                    let fromDate;
                    let toDate;
                    if (startdd !== "undefined") {
                        fromDate = new Date(startdd.substring(0, 4), scwin.LPAD(parseInt(startdd.substring(4, 6)) - 1), startdd.substring(6, 8), "09", "00");
                    }
                    if (enddd !== "undefined") {
                        toDate = new Date(enddd.substring(0, 4), scwin.LPAD(parseInt(enddd.substring(4, 6)) - 1), enddd.substring(6, 8), "19", "59");
                    }
                    if (scwin.precheckBeforeOpenNotice(fromDate, toDate)) {
                        await scwin.popupJsp();
                    }
                }
            } else {
                for (let i = 0; i < _cnt; i++) {
                    if (scwin.getCookie("pop_emergency" + $c.util.getComponent('dlt_popupResult').getCellData(i, 'contnId')) === "") {
                        startdd = $c.util.getComponent('dlt_popupResult').getCellData(i, 'notiDd');
                        enddd = $c.util.getComponent('dlt_popupResult').getCellData(i, 'endDd');
                        if (startdd !== "undefined") {
                            fromDate = new Date(startdd.substring(0, 4), scwin.LPAD(parseInt(startdd.substring(4, 6)) - 1), startdd.substring(6, 8), "09", "00");
                        }
                        if (enddd !== "undefined") {
                            toDate = new Date(enddd.substring(0, 4), scwin.LPAD(parseInt(enddd.substring(4, 6)) - 1), enddd.substring(6, 8), "19", "59");
                        }
                        if (scwin.precheckBeforeOpenNotice(fromDate, toDate)) {
                            await scwin.popupJspList(i);
                        }
                    }
                }
            }
        }
        if (scwin.getCookie("bndPopupJsp_01") === "") {
            fromDate = new Date("2023", "08", "07", "09", "00");
            toDate = new Date("2023", "08", "15", "23", "59");
            if (scwin.precheckBeforeOpenNotice(fromDate, toDate)) {
                await scwin.popupBnd01();
            }
        }
        if (scwin.getCookie("bndPopupJsp_tls") === "") {
            fromDate = new Date("2019", "09", "15", "09", "00");
            toDate = new Date("2019", "11", "15", "23", "59");
            if (scwin.precheckBeforeOpenNotice(fromDate, toDate)) {
                await scwin.popupBndTls();
            }
        }
        await scwin.showMessage();
        if (scwin.IEVersionCheck() > 10) {
            history.pushState(null, null, location.href);
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(login vs register) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_loginForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf00000.onpageload' });
    }
};

