/**
 * @method
 * @name setLoginType
 * @description set Login Type 처리
 * @param {String} pCorpUsrTpCd pCorpUsrTpCd
 * @returns {void}
 * @hidden N
 */
scwin.setLoginType = function (pCorpUsrTpCd) {
    const btna = $('div.login-selecter a.typea');
    const btnb = $('div.login-selecter a.typeb');
    const btnNewIsur = $('#mt20 img.btnNewIsur');
    const btnNewMember = $('#mt20 img.btnNewMember');
    const btnSrchInst = $('#mt20 img.btnSrchInst');
    btnSrchInst.css("display", "none");
    if (pCorpUsrTpCd === "71") {
        btna.addClass("active");
        btnb.removeClass("active");
        btnNewIsur.css("display", "");
        btnNewMember.css("display", "");
        btnSrchInst.css("display", "none");
        $c.util.getComponent("dma_loginReq").set("corpUsrTpCd", "71");
    } else {
        btnb.addClass("active");
        btna.removeClass("active");
        btnNewIsur.css("display", "none");
        btnNewMember.css("display", "none");
        btnSrchInst.css("display", "");
        $c.util.getComponent("dma_loginReq").set("corpUsrTpCd", "72");
    }
};

/**
 * @method
 * @name LPAD
 * @description LPAD 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.LPAD = function (val) {
    if (val < 10) {
        return "0" + "" + val;
    } else {
        return val;
    }
};

/**
 * @method
 * @name login
 * @description login 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.login = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_integUsrId').getValue().replace(/ /gi, "")) === 0) {
        await $c.win.alert("아이디를 입력하십시오.");
        $c.util.getComponent("ipt_integUsrId").setValue("");
        $c.util.getComponent("ipt_integUsrId").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypPw').getValue().replace(/ /gi, "")) === 0) {
            await $c.win.alert("비밀번호를 입력하십시오.");
            $c.util.getComponent("ipt_encrypPw").setValue("");
            $c.util.getComponent("ipt_encrypPw").focus();
            return false;
        }
    }
    scwin.form_loginForm.action = "/main/login.do?method=login";
    scwin.form_loginForm.target = "_self";
    await scwin.tx_fn_login();
};

/**
 * @method
 * @name showMessage
 * @description show Message 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showMessage = async function () {
    const message = (String(((dma_pageContext.get("message") ?? "")) == null ? '' : ((dma_pageContext.get("message") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("message") ?? "")) == null ? '' : ((dma_pageContext.get("message") ?? ""))));
    const errCode = (String(((dma_pageContext.get("errorCode") ?? "")) == null ? '' : ((dma_pageContext.get("errorCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("errorCode") ?? "")) == null ? '' : ((dma_pageContext.get("errorCode") ?? ""))));
    const failCnt = (String(((dma_pageContext.get("loginFailCnt") ?? "")) == null ? '' : ((dma_pageContext.get("loginFailCnt") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("loginFailCnt") ?? "")) == null ? '' : ((dma_pageContext.get("loginFailCnt") ?? ""))));
    const r_corp_usr_tp_cd = (String(((dma_pageContext.get("corp_usr_tp_cd") ?? "")) == null ? '' : ((dma_pageContext.get("corp_usr_tp_cd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("corp_usr_tp_cd") ?? "")) == null ? '' : ((dma_pageContext.get("corp_usr_tp_cd") ?? ""))));
    scwin.setLoginType(r_corp_usr_tp_cd);
    if (errCode === 'ERROR-9207') {
        if (await $c.win.confirm(message)) {
            const r_integ_usr_id = (String(((dma_pageContext.get("integ_usr_id") ?? "")) == null ? '' : ((dma_pageContext.get("integ_usr_id") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("integ_usr_id") ?? "")) == null ? '' : ((dma_pageContext.get("integ_usr_id") ?? ""))));
            const r_encryp_pw = (String(((dma_pageContext.get("encryp_pw") ?? "")) == null ? '' : ((dma_pageContext.get("encryp_pw") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("encryp_pw") ?? "")) == null ? '' : ((dma_pageContext.get("encryp_pw") ?? ""))));
            $c.util.getComponent('dma_loginReq').set('reloginYn', "Y");
            $c.util.getComponent("ipt_integUsrId").setValue(r_integ_usr_id);
            $c.util.getComponent("ipt_encrypPw").setValue(r_encryp_pw);
            scwin.form_loginForm.action = "/main/login.do?method=login";
            scwin.form_loginForm.target = "_self";
            await scwin.tx_fn_showMessage();
            return;
        }
    } else {
        await $c.win.alert(message);
    }
};

