/**
 * @method
 * @name IEVersionCheck
 * @description IEVersion Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.IEVersionCheck = function () {
    let word;
    let version = "N/A";
    const agent = navigator.userAgent.toLowerCase();
    const name = navigator.appName;
    if (name === "Microsoft Internet Explorer") {
        word = "msie ";
    } else {
        if (agent.search("trident") > -1) {
            word = "trident/.*rv:";
        } else {
            if (agent.search("edge/") > -1) {
                word = "edge/";
            }
        }
    }
    const reg = new RegExp(word + "([0-9]{1,})(\\.{0,}[0-9]{0,1})");
    if (reg.exec(agent) != null) {
        version = RegExp.$1 + RegExp.$2;
    }
    return version;
};

/**
 * @method
 * @name mainc_relocate
 * @description mainc relocate 처리
 * @returns {void}
 * @hidden N
 */
scwin.mainc_relocate = function () {
    const scr_w = $('html').width();
    const mainc_w = $('#wrapper-main').width();
    const tw = Number((scr_w - mainc_w) / 2);
    if (tw > 0) {
        $('#wrapper-main').css({ "margin-left": tw + "px" });
    } else {
        $('#wrapper-main').css({ "margin-left": "0px" });
    }
};

/**
 * @method
 * @name login_type_init
 * @description login type init 처리
 * @returns {void}
 * @hidden N
 */
scwin.login_type_init = function () {
    const btna = $('div.login-selecter a.typea');
    const btnb = $('div.login-selecter a.typeb');
    const divFind = $('div.find');
    const btnNewIsur = $('div.mt20 img.btnNewIsur');
    const btnNewMember = $('div.mt20 img.btnNewMember');
    const btnSrchInst = $('div.mt20 img.btnSrchInst');
    btnSrchInst.css("display", "none");
    btna.bind("click focus", function() {
            $(this).addClass("active");
            btnb.removeClass("active");
            divFind.css("display", "");
            btnNewIsur.css("display", "");
            btnNewMember.css("display", "");
            btnSrchInst.css("display", "none");
            $c.util.getComponent("dma_loginReq").set("corpUsrTpCd", "71");
    });
    btnb.bind("click focus", function() {
            $(this).addClass("active");
            btna.removeClass("active");
            divFind.css("display", "none");
            btnNewIsur.css("display", "none");
            btnNewMember.css("display", "none");
            btnSrchInst.css("display", "");
            $c.util.getComponent("dma_loginReq").set("corpUsrTpCd", "72");
    });
};
